<?php
declare(strict_types=1);

/** MariaDB/InnoDB schema, deliberately trigger-free for shared-hosting imports. */
function installMariaSchema(PDO $pdo, bool $seedRuntimeRows=true): void {
    $ddl = [
        "CREATE TABLE IF NOT EXISTS agencies (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, phone VARCHAR(35) NULL, active TINYINT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY i_agencies_active (active,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, agency_id BIGINT UNSIGNED NULL, username VARCHAR(191) NOT NULL UNIQUE, pass VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, fails INT NOT NULL DEFAULT 0, locked_until BIGINT NOT NULL DEFAULT 0, display_name VARCHAR(180) NULL, phone VARCHAR(35) NULL, session_version INT NOT NULL DEFAULT 0, KEY i_users_agency (agency_id), CONSTRAINT fk_users_agency FOREIGN KEY (agency_id) REFERENCES agencies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS accounts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, agency_id BIGINT UNSIGNED NOT NULL, name VARCHAR(180) NOT NULL, phone VARCHAR(35) NULL, kind VARCHAR(30) NOT NULL DEFAULT 'customer', opening BIGINT NOT NULL DEFAULT 0, archived TINYINT NOT NULL DEFAULT 0, UNIQUE KEY uq_accounts_tenant (id,agency_id), KEY i_a (agency_id), CONSTRAINT ck_accounts_opening CHECK (opening BETWEEN -9999999999999 AND 9999999999999), CONSTRAINT fk_accounts_agency FOREIGN KEY (agency_id) REFERENCES agencies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS entries (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, agency_id BIGINT UNSIGNED NOT NULL, account_id BIGINT UNSIGNED NOT NULL, edate CHAR(10) NOT NULL, note TEXT NULL, ref VARCHAR(100) NULL, debit BIGINT NOT NULL DEFAULT 0, credit BIGINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, reverses_entry_id BIGINT UNSIGNED NULL, cat VARCHAR(40) NOT NULL DEFAULT 'other', deleted TINYINT NOT NULL DEFAULT 0, bill_id BIGINT UNSIGNED NULL, linked_entry_id BIGINT UNSIGNED NULL, request_key VARCHAR(48) CHARACTER SET ascii COLLATE ascii_bin NULL, currency CHAR(3) NOT NULL DEFAULT 'PKR', fx_rate BIGINT NOT NULL DEFAULT 1000000, foreign_amount BIGINT NOT NULL DEFAULT 0, UNIQUE KEY uq_entries_tenant (id,agency_id,account_id), UNIQUE KEY uq_entry_request (agency_id,request_key), KEY i_e (agency_id,account_id,edate,id), KEY i_active_e (agency_id,account_id,deleted,edate,id), KEY i_e_report (agency_id,deleted,edate,cat), KEY i_report_date (agency_id,deleted,edate), KEY i_bill_payments (agency_id,bill_id,deleted), KEY i_entry_links (agency_id,account_id,linked_entry_id,deleted), KEY i_rev (reverses_entry_id), CONSTRAINT ck_entry_amounts CHECK (debit >= 0 AND credit >= 0 AND debit <= 9999999999999 AND credit <= 9999999999999 AND ((debit = 0 AND credit > 0) OR (credit = 0 AND debit > 0))), CONSTRAINT ck_entry_deleted CHECK (deleted IN (0,1)), CONSTRAINT ck_entry_fx CHECK (fx_rate > 0 AND fx_rate <= 100000000000 AND foreign_amount > 0 AND foreign_amount <= 9999999999999), CONSTRAINT fk_entries_account FOREIGN KEY (account_id,agency_id) REFERENCES accounts(id,agency_id), CONSTRAINT fk_entries_bill FOREIGN KEY (bill_id,agency_id,account_id) REFERENCES entries(id,agency_id,account_id), CONSTRAINT fk_entries_link FOREIGN KEY (linked_entry_id,agency_id,account_id) REFERENCES entries(id,agency_id,account_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS audit_log (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, agency_id BIGINT UNSIGNED NULL, user_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, entity VARCHAR(80) NULL, entity_id BIGINT NULL, details TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY audit_agency (agency_id,created_at), KEY i_audit_user (user_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS login_limits (rate_key CHAR(64) NOT NULL PRIMARY KEY, attempts INT NOT NULL, until_time BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin",
        "CREATE TABLE IF NOT EXISTS chat_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, agency_id BIGINT UNSIGNED NOT NULL, sender_id BIGINT UNSIGNED NOT NULL, from_master TINYINT NOT NULL, body VARCHAR(2000) NOT NULL, request_key VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, read_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, is_auto TINYINT NOT NULL DEFAULT 0, UNIQUE KEY uq_chat_request (sender_id,request_key), KEY i_chat_thread (agency_id,id), KEY i_chat_unread (from_master,read_at,agency_id), KEY i_chat_rate (sender_id,created_at,is_auto), KEY i_chat_pending (agency_id,from_master,read_at,id), CONSTRAINT ck_chat_flags CHECK (from_master IN (0,1) AND is_auto IN (0,1)), CONSTRAINT fk_chat_agency FOREIGN KEY (agency_id) REFERENCES agencies(id), CONSTRAINT fk_chat_sender FOREIGN KEY (sender_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS chat_presence (id TINYINT NOT NULL PRIMARY KEY, mode VARCHAR(10) NOT NULL DEFAULT 'available', last_seen BIGINT NOT NULL DEFAULT 0, CONSTRAINT ck_presence_id CHECK (id=1), CONSTRAINT ck_presence_mode CHECK (mode IN ('available','away'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS chat_threads (agency_id BIGINT UNSIGNED NOT NULL PRIMARY KEY, last_id BIGINT UNSIGNED NOT NULL DEFAULT 0, unread_master BIGINT UNSIGNED NOT NULL DEFAULT 0, unread_agent BIGINT UNSIGNED NOT NULL DEFAULT 0, bot_topic VARCHAR(40) NOT NULL DEFAULT '', bot_count INT NOT NULL DEFAULT 0, last_bot_at BIGINT NOT NULL DEFAULT 0, human_until BIGINT NOT NULL DEFAULT 0, waiting TINYINT NOT NULL DEFAULT 0, KEY i_chat_last (last_id,agency_id), CONSTRAINT fk_chat_threads_agency FOREIGN KEY (agency_id) REFERENCES agencies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS ledger_schema (version INT NOT NULL PRIMARY KEY, applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
    ];
    foreach ($ddl as $sql) $pdo->exec($sql);
    $pdo->exec('INSERT IGNORE INTO ledger_schema(version) VALUES (1)');
    if($seedRuntimeRows)$pdo->exec("INSERT IGNORE INTO chat_presence(id,mode,last_seen) VALUES (1,'available',0)");
}

function upgradeMariaSchemaV2(PDO $pdo):void{
    $version=(int)$pdo->query('SELECT MAX(version) FROM ledger_schema')->fetchColumn();
    if($version>=2)return;
    $columns=$pdo->query("SHOW COLUMNS FROM entries")->fetchAll(PDO::FETCH_COLUMN);
    if(!in_array('currency',$columns,true))$pdo->exec("ALTER TABLE entries ADD currency CHAR(3) NOT NULL DEFAULT 'PKR'");
    if(!in_array('fx_rate',$columns,true))$pdo->exec('ALTER TABLE entries ADD fx_rate BIGINT NOT NULL DEFAULT 1000000');
    if(!in_array('foreign_amount',$columns,true))$pdo->exec('ALTER TABLE entries ADD foreign_amount BIGINT NOT NULL DEFAULT 0');
    $pdo->exec('UPDATE entries SET foreign_amount=debit+credit WHERE foreign_amount=0');
    try{$pdo->exec('ALTER TABLE entries ADD CONSTRAINT ck_entry_fx CHECK (fx_rate > 0 AND fx_rate <= 100000000000 AND foreign_amount > 0 AND foreign_amount <= 9999999999999)');}catch(PDOException $ex){if(!str_contains(strtolower($ex->getMessage()),'duplicate'))throw $ex;}
    $codes="'PKR','USD','EUR','GBP','AED','SAR','QAR','KWD','BHD','OMR','TRY','CNY','CAD','AUD','SGD','MYR','THB','JPY','INR','BDT','NPR'";
    try{$pdo->exec("ALTER TABLE entries ADD CONSTRAINT ck_entry_currency CHECK (currency IN ($codes) AND (currency<>'PKR' OR fx_rate=1000000))");}catch(PDOException $ex){if(!str_contains(strtolower($ex->getMessage()),'duplicate'))throw $ex;}
    try{$pdo->exec('ALTER TABLE entries ADD CONSTRAINT ck_entry_fx_match CHECK (debit+credit=ROUND(foreign_amount*fx_rate/1000000))');}catch(PDOException $ex){if(!str_contains(strtolower($ex->getMessage()),'duplicate'))throw $ex;}
    $pdo->exec('INSERT IGNORE INTO ledger_schema(version) VALUES (2)');
}
